1	//! Tests for Innistrad Tier 5 cards.
2	
3	mod common;
4	
5	use common::*;
6	use mtg_engine::actions::Target;
7	use mtg_engine::cards::CardRegistry;
8	use mtg_engine::combat;
9	use mtg_engine::engine;
10	use mtg_engine::ids::CardId;
11	use mtg_engine::sba::check_state_based_actions_with_registry;
12	use mtg_engine::triggers;
13	use mtg_engine::types::*;
14	
15	fn registry() -> CardRegistry {
16	    CardRegistry::with_all_cards()
17	}
18	
19	// ── Spirit lords ───────────────────────────────────────────────────
20	
21	/// Battleground Geist gives other Spirits +1/+0 but not itself.
22	#[test]
23	fn battleground_geist_buffs_other_spirits() {
24	    let reg = registry();
25	    let mut state = game_at_step(Step::PrecombatMain, P0);
26	
27	    let geist = named_creature(&mut state, &reg, "Battleground Geist", P0);
28	    let spirit = named_creature(&mut state, &reg, "Chapel Geist", P0);
29	    let non_spirit = ready_creature(&mut state, P0, 2, 2);
30	
31	    // Battleground Geist: 3/3 base. Should NOT buff itself ("other").
32	    assert_eq!(state.effective_power(geist, &reg), Some(3));
33	    // Chapel Geist: 2/3 base + 1/0 from lord = 3/3.
34	    assert_eq!(state.effective_power(spirit, &reg), Some(3));
35	    assert_eq!(state.effective_toughness(spirit, &reg), Some(3));
36	    // Non-spirit: no buff.
37	    assert_eq!(state.effective_power(non_spirit, &reg), Some(2));
38	}
39	
40	/// Gallows Warden gives other Spirits +0/+1 but not itself.
41	#[test]
42	fn gallows_warden_buffs_other_spirits() {
43	    let reg = registry();
44	    let mut state = game_at_step(Step::PrecombatMain, P0);
45	
46	    let warden = named_creature(&mut state, &reg, "Gallows Warden", P0);
47	    let spirit = named_creature(&mut state, &reg, "Chapel Geist", P0);
48	
49	    // Warden: 3/3 base, should NOT buff itself.
50	    assert_eq!(state.effective_toughness(warden, &reg), Some(3));
51	    // Chapel Geist: 2/3 base + 0/1 from warden = 2/4.
52	    assert_eq!(state.effective_toughness(spirit, &reg), Some(4));
53	    assert_eq!(state.effective_power(spirit, &reg), Some(2));
54	}
55	
56	/// Spirit lords don't buff opponent's spirits.
57	#[test]
58	fn spirit_lord_doesnt_buff_opponent() {
59	    let reg = registry();
60	    let mut state = game_at_step(Step::PrecombatMain, P0);
61	
62	    let _geist = named_creature(&mut state, &reg, "Battleground Geist", P0);
63	    let enemy_spirit = named_creature(&mut state, &reg, "Chapel Geist", P1);
64	
65	    // Opponent's spirit should NOT get the buff.
66	    assert_eq!(state.effective_power(enemy_spirit, &reg), Some(2));
67	}
68	
69	// ── Dynamic P/T ────────────────────────────────────────────────────
70	
71	/// Geist-Honored Monk P/T equals creatures you control, ETB creates 2 tokens.
72	#[test]
73	fn geist_honored_monk_dynamic_pt_and_tokens() {
74	    let reg = registry();
75	    let mut state = game_at_step(Step::PrecombatMain, P0);
76	
77	    let monk = castable_spell(&mut state, &reg, "Geist-Honored Monk", P0);
78	
79	    // Give P0 a library so draw doesn't fail.
80	    let land_id = reg.get_id_by_name("Forest").unwrap();
81	    for _ in 0..5 {
82	        let id = state.create_object(land_id, P0, Zone::Library, None, None);
83	        state.get_player_mut(P0).library_order.push(id);
84	    }
85	
86	    state = cast_and_resolve(&state, &reg, monk, vec![]);
87	    triggers::process_triggers(&mut state, &reg);
88	
89	    // Monk + 2 Spirit tokens = 3 creatures.
90	    let creatures: Vec<_> = state.objects.values()
91	        .filter(|o| o.zone == Zone::Battlefield && o.controller == P0 && o.power.is_some())
92	        .collect();
93	    assert_eq!(creatures.len(), 3, "Monk + 2 Spirit tokens");
94	
